import datetime as dt
holidays = {dt.date(2026,11,20), dt.date(2026,12,8), dt.date(2026,12,25), dt.date(2026,12,24),
            dt.date(2026,12,31), dt.date(2027,1,1)}
# recesso 2026-12-20..2027-01-20 inclusive
def indisponivel(d):
    return d.weekday()>=5 or d in holidays or (dt.date(2026,12,20) <= d <= dt.date(2027,1,20))
def conta(termo, n):
    d,k = termo,0
    while k<n:
        d += dt.timedelta(days=1)
        if not indisponivel(d): k+=1
    return d
# hipótese hipotética de prazo em dobro (30 dias úteis) mesmo termo inicial
print("contestacao EM DOBRo (30 d.u. a partir de 24/11/2026):", conta(dt.date(2026,11,24), 30))
print("apelacao EM DOBRo (30 d.u. a partir de 14/12/2026):", conta(dt.date(2026,12,14), 30))
print("embargos em dobro (10 d.u. a partir de 14/12/2026):", conta(dt.date(2026,12,14), 10))
EOF"}
